package com.smarthub.plus;
import android.content.Context;import android.os.Build;import android.provider.Settings;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Reads this receiver's normally accessible properties; no private vendor files or borrowed tokens. */
final class FactoryIdentity {
 static String property(String name){try{Process p=new ProcessBuilder("/system/bin/getprop",name).redirectErrorStream(true).start();String value;try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream(),StandardCharsets.UTF_8))){value=r.readLine();}p.waitFor();return value!=null&&value.length()<=128&&value.matches("[A-Za-z0-9:._-]*")&&!value.equalsIgnoreCase("unknown")?value:"";}catch(Exception e){return "";}}
 private static String first(String... keys){for(String k:keys){String s=property(k);if(!s.isEmpty())return s;}return "";}
 static JSONObject read(Context c)throws Exception{JSONObject saved=FactoryVault.read(c).optJSONObject("identity");if(saved!=null&&valid(saved))return saved;JSONObject j=new JSONObject();j.put("sn",first("persist.sys.sn","ro.serialno"));j.put("chipId",first("persist.sys.chipid"));for(String name:new String[]{"cid","pid","mid"}){String alternate=name.equals("mid")?"hid":name;String value=first("ro.device."+name,"persist.sys."+alternate);int id=-1;try{id=Integer.parseInt(value);}catch(Exception ignored){}j.put(name,id);}return j;}
 static boolean valid(JSONObject j){return j!=null&&j.optString("sn").matches("[A-Za-z0-9._:-]{4,64}")&&j.optInt("cid",-1)>=0&&j.optInt("pid",-1)>=0&&j.optInt("mid",-1)>=0;}
 static JSONObject payload(Context c,JSONObject id,String user,String password)throws Exception{JSONObject j=new JSONObject(id.toString());String sn=id.getString("sn"),chip=id.optString("chipId");j.remove("chipId");j.put("username",user==null?"":user);j.put("password",password==null?"":password);if(sn.length()==12){boolean chipAvailable=!chip.isEmpty()&&!chip.equals("1234");j.put(chipAvailable?"chipId":"authenticator",FactoryProtocol.authenticator(sn,chipAvailable?chip:sn));}j.put("androidId",Settings.Secure.getString(c.getContentResolver(),Settings.Secure.ANDROID_ID));j.put("androidVersion",Build.VERSION.RELEASE);j.put("brand",Build.BRAND);j.put("model",Build.MODEL);j.put("manufacturer",Build.MANUFACTURER);j.put("device",Build.DEVICE);j.put("hardware",Build.HARDWARE);j.put("board",Build.BOARD);j.put("appVersion",c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName);j.put("appName","IRAQhub");j.put("app","IRAQhub");j.put("terminalType","AndroidStb");j.put("timezone",java.time.ZonedDateTime.now().getOffset().getId());j.put("language","English");return j;}
}
